import { describe, expect, it } from "vitest";
import {
  formatGregorianDateOnly,
  formatJalaliDate,
  jalaliParts,
  parseGregorianDateOnly,
  todayGregorianISO,
} from "@/lib/doran";

/**
 * Reference pairs are fixed from independently published calendar knowledge
 * (Nowruz dates and month arithmetic), never generated by the functions under
 * test.
 *
 * Known anchors:
 *  - 1 Farvardin 1403 = 2024-03-20, 1404 = 2025-03-21, 1405 = 2026-03-21
 *    (1403 is a leap year: Esfand has 30 days).
 *  - Months 1–6 have 31 days: Khordad 31, 1404 = 2025-06-21; Tir 1 = 2025-06-22.
 *  - Mehr has 30 days: Aban 1, 1405 = 2026-10-23 → Aban 9 = 2026-10-31.
 */
describe("Gregorian/Jalali boundary", () => {
  it("maps known Gregorian dates to the expected Jalali fields", () => {
    expect(jalaliParts("2024-03-20")).toEqual({ year: 1403, month: 1, day: 1 });
    expect(jalaliParts("2025-03-21")).toEqual({ year: 1404, month: 1, day: 1 });
    expect(jalaliParts("2026-03-21")).toEqual({ year: 1405, month: 1, day: 1 });
    expect(jalaliParts("2026-10-31")).toEqual({ year: 1405, month: 8, day: 9 });
  });

  it("round-trips date-only values without shifting the calendar day", () => {
    for (const g of ["2024-03-20", "2025-06-22", "2026-10-31", "2025-03-20"]) {
      const d = parseGregorianDateOnly(g);
      expect(d, g).not.toBeNull();
      expect(formatGregorianDateOnly(d)).toBe(g);
    }
  });

  it("handles the 1403 leap year and month boundaries", () => {
    // Last day of Esfand in the leap year 1403 (30 days) is 2025-03-20...
    expect(jalaliParts("2025-03-20")).toEqual({ year: 1403, month: 12, day: 30 });
    // ...and the non-leap 1404 ends one day earlier in the Gregorian year.
    expect(jalaliParts("2026-03-20")).toEqual({ year: 1404, month: 12, day: 29 });
    // Last day of a 31-day month and the first day of the next.
    expect(jalaliParts("2025-06-21")).toEqual({ year: 1404, month: 3, day: 31 });
    expect(jalaliParts("2025-06-22")).toEqual({ year: 1404, month: 4, day: 1 });
  });

  it("serializes a picked Jalali date back to the correct Gregorian day", () => {
    // Pick 1 Farvardin 1405 from the calendar (constructed via Jalali fields
    // through the boundary's parser output of a known Gregorian day).
    const nowruz = parseGregorianDateOnly("2026-03-21");
    expect(formatGregorianDateOnly(nowruz)).toBe("2026-03-21");
    // Aban 9, 1405 → 2026-10-31.
    const aban9 = parseGregorianDateOnly("2026-10-31");
    expect(formatGregorianDateOnly(aban9)).toBe("2026-10-31");
  });

  it("is independent of the host timezone for date-only parsing", () => {
    // The value is parsed by field extraction anchored to Asia/Tehran — never
    // via `new Date("YYYY-MM-DD")` (UTC) or a local Date. Assert both the
    // Gregorian Tehran parts and the Jalali fields are the intended day.
    const d = parseGregorianDateOnly("2026-10-31");
    expect(d).not.toBeNull();
    const g = d!.toGregorianParts();
    expect([g.year, g.month, g.day]).toEqual([2026, 10, 31]);
    expect(jalaliParts("2026-10-31")).toEqual({ year: 1405, month: 8, day: 9 });
  });

  it("rejects non-date-only values instead of misparsing them", () => {
    // A date-time instant is not a date-only field: refuse rather than guess.
    expect(parseGregorianDateOnly("2026-10-31T14:30:00Z")).toBeNull();
    expect(parseGregorianDateOnly("not-a-date")).toBeNull();
    expect(parseGregorianDateOnly("2026-13-01")).toBeNull();
    expect(parseGregorianDateOnly("2026-00-10")).toBeNull();
    expect(parseGregorianDateOnly("2026-10-00")).toBeNull();
  });

  it("preserves empty and optional values", () => {
    expect(parseGregorianDateOnly(null)).toBeNull();
    expect(parseGregorianDateOnly(undefined)).toBeNull();
    expect(parseGregorianDateOnly("")).toBeNull();
    expect(parseGregorianDateOnly("   ")).toBeNull();
    // Clearing the picker round-trips to null → "" at the form boundary.
    expect(formatGregorianDateOnly(null)).toBeNull();
    expect(formatGregorianDateOnly(undefined)).toBeNull();
  });

  it("formats for display in the Persian calendar", () => {
    expect(formatJalaliDate("2026-10-31")).toBe("۱۴۰۵/۰۸/۰۹");
    expect(formatJalaliDate("2026-03-21")).toBe("۱۴۰۵/۰۱/۰۱");
  });

  it("keeps fallbacks for display of unparseable or empty values", () => {
    expect(formatJalaliDate(null)).toBe("—");
    expect(formatJalaliDate(undefined)).toBe("—");
    expect(formatJalaliDate("")).toBe("—");
    // Defensive: an unexpected shape echoes the raw string, never invents one.
    expect(formatJalaliDate("2026-10-31T14:30:00Z")).toBe("2026-10-31T14:30:00Z");
  });

  it("serializes today in the canonical API shape", () => {
    expect(todayGregorianISO()).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });
});
